        // to just "<key>". Revert to EF8 format for existing data compatibility.
        entity.HasPartitionKey(p => p.Id);
    });

    // Preserve EF8 id format: "Product|<key>"
    modelBuilder.Entity<Product>().Property(p => p.Id)
        .HasConversion(
            v => v,
            v => v);
}

